import queue


def accepted(cap: int, xs: list[int]) -> int:
    """Count the puts accepted by a bounded queue before it is full.

    Creates a queue holding at most `cap` integers and tries to put each
    element of `xs` in order without blocking. Stops at the first put that
    finds the queue full and returns the number of puts accepted so far.
    Nothing is ever taken out of the queue.

    A capacity of zero or less means the queue can hold nothing, so the
    result is 0 (unlike queue.Queue, where maxsize <= 0 means unbounded).
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_accepted_cap_smaller_than_input() -> None:
    assert accepted(3, [10, 20, 30, 40, 50]) == 3


def test_accepted_cap_equal_to_length() -> None:
    assert accepted(4, [1, 2, 3, 4]) == 4


def test_accepted_cap_larger_than_input() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_accepted_empty_input() -> None:
    assert accepted(5, []) == 0


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_negative_capacity() -> None:
    assert accepted(-2, [1, 2, 3]) == 0


def test_accepted_capacity_one() -> None:
    assert accepted(1, [7, 8, 9]) == 1


def test_accepted_duplicates_count_separately() -> None:
    assert accepted(2, [5, 5, 5, 5]) == 2
